  /// NF3REG, NF3DIR, NF3BLK, ...
  @ffi.Uint32()
  external int type;

  @ffi.Uint32()
  external int mode;

  @ffi.Uint64()
  external int size;

  external timeval atime;

  external timeval mtime;

  external timeval ctime;

  @ffi.Uint32()
  external int uid;

  @ffi.Uint32()
  external int gid;

  @ffi.Uint32()
  external int nlink;

  @ffi.Uint64()
  external int dev;

  @ffi.Uint64()
  external int rdev;

  @ffi.Uint64()
  external int blksize;

  @ffi.Uint64()
  external int blocks;

  @ffi.Uint64()
  external int used;

  @ffi.Uint32()
  external int atime_nsec;

  @ffi.Uint32()
  external int mtime_nsec;

  @ffi.Uint32()
  external int ctime_nsec;
}

final class nfsfh extends ffi.Opaque {}

final class timeval extends ffi.Struct {
  @ffi.Long()
  external int tv_sec;

  @ffi.Long()
  external int tv_usec;

  static ffi.Pointer<timeval> $allocate(
    ffi.Allocator $allocator, {
    required int tv_sec,
    required int tv_usec,
  }) => $allocator<timeval>()
    ..ref.tv_sec = tv_sec
    ..ref.tv_usec = tv_usec;
}
